    from pathfinding.core.diagonal_movement import DiagonalMovement
    import hashlib
    MIN_DIF = 5.0  #这里修改最低等级
    notuser=1
    black = "⚫"
    white = "⚪"
    wall = "██"
    goal = "🔷"
    cnt = 0
    zd = "💣"
    ljlj="🟦"
