    startplayer = []

    def clear_screen():
        print("\033c", end="")
        try:
            import os
            if os.name == "nt":
                cmd = "cls"
            else:
                cmd = "clear"
            os.system(cmd)
        except BaseException:
            print("\n"*50)

    def generate_positions():
        global lj, dif
        total_try = 0
        while 1:
            print(total_try,end="")
            print("\r",end="")
            total_try += 1
            player = None
            while True:
                rx = random.randint(1, k)
                ry = random.randint(1, kk)
                player = [rx, ry]
                break
            target = None
            while True:
                rx = random.randint(1, k)
                ry = random.randint(1, kk)
                target = [rx, ry]
                if target != player:
                    break
            num_walls = random.randint(80, 360)
            walls = []
            while len(walls) < num_walls:
                wx = random.randint(1, k)
                wy = random.randint(1, kk)
                wall_pos = [wx, wy]
                if wall_pos != player and wall_pos != target and wall_pos not in walls:
                    walls.append(wall_pos)
            matrix = []
            for gy in range(1, kk + 1):
                row = []
                for gx in range(1, k + 1):
                    if [gx, gy] in walls:
                        row.append(0)
                    else:
                        row.append(1)
                matrix.append(row)
            px, py = player
            tx, ty = target
            matrix[py - 1][px - 1] = 1
            matrix[ty - 1][tx - 1] = 1
            grid = Grid(matrix=matrix)
            finder = AStarFinder(diagonal_movement=DiagonalMovement.never)
            n, m = player
            o, p = target
            start = grid.node(n - 1, m - 1)
            end = grid.node(o - 1, p - 1)
            path, runs = finder.find_path(start, end, grid)
            if path != []:
                lj = list(path)
                d = [ (n.x+1, n.y+1) for n in lj ]
                lj=d.copy()
                max_len = 58
                raw = len(lj) / max_len
                dif = round(raw * 5.0, 1)
                if dif >= MIN_DIF:
                    print(f"本次迷宫难度:{dif},一共尝试生成 {total_try} 次")
                    return player, target, walls

